package i18n

// catalogo son las cadenas de las pantallas del IdP en los cinco idiomas de
// producto. El inglés es el original y el resto son traducciones.
//
// Convenio de claves: <pantalla>.<elemento>. Agrupadas por pantalla para que al
// tocar una se vea de un vistazo lo que la rodea, y no por idioma, que obligaría
// a saltar entre cinco bloques para comprobar una sola frase.
//
// Un test verifica que ninguna clave se queda sin alguno de los cinco idiomas:
// una traducción que falta cae al inglés en medio de una pantalla en español, y
// eso no lo ve nadie hasta que se queja un cliente.
